package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var x, y, l, r int64
	fmt.Fscan(in, &x, &y, &l, &r)

	unlucky := make(map[int64]bool)

	// generate powers of x
	powsX := []int64{1}
	if x != 1 {
		for {
			next := powsX[len(powsX)-1] * x
			if next < 0 || next > r { // overflow or beyond r
				break
			}
			powsX = append(powsX, next)
		}
	}

	// generate powers of y
	powsY := []int64{1}
	if y != 1 {
		for {
			next := powsY[len(powsY)-1] * y
			if next < 0 || next > r {
				break
			}
			powsY = append(powsY, next)
		}
	}

	// generate all unlucky years within [l, r]
	for _, px := range powsX {
		for _, py := range powsY {
			sum := px + py
			if sum < l {
				continue
			}
			if sum > r {
				break
			}
			unlucky[sum] = true
		}
	}

	if len(unlucky) == 0 {
		fmt.Println(r - l + 1)
		return
	}

	years := make([]int64, 0, len(unlucky))
	for k := range unlucky {
		years = append(years, k)
	}
	sort.Slice(years, func(i, j int) bool { return years[i] < years[j] })

	var ans int64 = 0

	// gap before first unlucky year
	if years[0] > l {
		ans = years[0] - l
	}

	// gaps between unlucky years
	for i := 1; i < len(years); i++ {
		if years[i]-years[i-1] > 1 {
			length := years[i] - years[i-1] - 1
			if length > ans {
				ans = length
			}
		}
	}

	// gap after last unlucky year
	if years[len(years)-1] < r {
		length := r - years[len(years)-1]
		if length > ans {
			ans = length
		}
	}

	fmt.Println(ans)
}

